// runScript establishes an SSH connection to the machine runtime, executes the
// given script, and records WorkloadEvent records for the captured output and
// exit status.  Returns the derived workload instance status.
func runScript(
	r *controller.Reconciler,
	mwi *v0.MachineWorkloadInstance,
	mri *v0.MachineRuntimeInstance,
	mwd *v0.MachineWorkloadDefinition,
	script string,
	scriptName string,
	log *logr.Logger,
) status.WorkloadInstanceStatus {
	// establish ssh connection to the runtime
	sshClient, _, err := machine.GetClient(mri, r.EncryptionKey)
	if err != nil {
		// ssh failure is user-visible — the machine isn't reachable
		if eventErr := r.EventsRecorder.RecordEvent(
			&v0.Event{
				Type:   util.Ptr(event.TypeWarning),
				Reason: util.Ptr("SSHConnectFailed"),
				Note:   util.Ptr(fmt.Sprintf("failed to connect to machine runtime instance: %s", err)),
			},
			*mwi.ID,
			mwi.GetFullyQualifiedType(),
		); eventErr != nil {
			log.Error(eventErr, "failed to record event for ssh connect error")
		}
		return status.WorkloadInstanceStatusError
	}
	defer sshClient.Close()

	// decrypt env from definition and instance
	defEnv, err := machine.DecryptEnv(mwd.Env, r.EncryptionKey)
	if err != nil {
		log.Error(err, "failed to decrypt definition env")
		return status.WorkloadInstanceStatusError
	}
	instEnv, err := machine.DecryptEnv(mwi.Env, r.EncryptionKey)
	if err != nil {
		log.Error(err, "failed to decrypt instance env")
		return status.WorkloadInstanceStatusError
	}

	// merge env - instance env overrides definition env on duplicate keys
	effectiveEnv := machine.MergeEnv(defEnv, instEnv)

	// resolve shell and working dir defaults
	shell := util.DerefString(mwd.Shell)
	if shell == "" {
		shell = defaultShell
	}
	workDir := util.DerefString(mwd.WorkingDir)

	// run the script on the remote machine
	stdout, stderr, exitCode, timedOut, connectionErr := runRemoteScript(
		sshClient,
		script,
		shell,
		workDir,
		effectiveEnv,
		mwd.Timeout,
	)

	// derive status and record events based on execution result
	var wlStatus status.WorkloadInstanceStatus
	var reason, eventType, message string
	switch {
	case timedOut:
		wlStatus = status.WorkloadInstanceStatusDown
		reason = "ScriptTimedOut"
		eventType = event.TypeWarning
		message = fmt.Sprintf("%s script timed out (stderr: %s)", scriptName, truncateMessage(sanitizeScriptOutput(stderr)))
	case connectionErr != nil:
		wlStatus = status.WorkloadInstanceStatusError
		reason = "ConnectionFailed"
		eventType = event.TypeWarning
		message = fmt.Sprintf("%s script connection error: %s", scriptName, connectionErr.Error())
	case exitCode == 0:
		wlStatus = status.WorkloadInstanceStatusHealthy
		reason = "ScriptSucceeded"
		eventType = event.TypeNormal
		message = fmt.Sprintf("%s script completed successfully (stdout: %s)", scriptName, truncateMessage(sanitizeScriptOutput(stdout)))
	default:
		wlStatus = status.WorkloadInstanceStatusUnhealthy
		reason = "ScriptFailed"
		eventType = event.TypeWarning
		message = fmt.Sprintf("%s script failed with exit code %d (stderr: %s)", scriptName, exitCode, truncateMessage(sanitizeScriptOutput(stderr)))
	}
	if eventErr := r.EventsRecorder.RecordEvent(
		&v0.Event{
			Type:   util.Ptr(eventType),
			Reason: util.Ptr(reason),
			Note:   util.Ptr(truncateMessage(message)),
		},
		*mwi.ID,
		mwi.GetFullyQualifiedType(),
	); eventErr != nil {
		log.Error(eventErr, "failed to record event")
	}

	return wlStatus
}

// runRemoteScript executes the given script on the remote over the existing
// SSH client, returning captured stdout, stderr, exit code, a timeout flag,
// and any connection error.
func runRemoteScript(
	client *ssh.Client,
	script string,
	shell string,
	workingDir string,
	env []string,
	timeout *int,
) (stdout string, stderr string, exitCode int, timedOut bool, err error) {
	session, err := client.NewSession()
	if err != nil {
		return "", "", -1, false, fmt.Errorf("failed to create ssh session: %w", err)
	}
	defer session.Close()

	// assemble the full script: cd + env exports + user script
	fullScript := buildScript(script, workingDir, env)

	// attach stdout/stderr buffers
	var stdoutBuf, stderrBuf bytes.Buffer
	session.Stdout = &stdoutBuf
	session.Stderr = &stderrBuf

	// attach stdin pipe for the script body
	stdinPipe, err := session.StdinPipe()
	if err != nil {
		return "", "", -1, false, fmt.Errorf("failed to open ssh stdin pipe: %w", err)
	}

	// build context for timeout handling
	ctx := context.Background()
	var cancel context.CancelFunc
	if timeout != nil && *timeout > 0 {
		ctx, cancel = context.WithTimeout(ctx, time.Duration(*timeout)*time.Second)
		defer cancel()
	}

	// start `<shell> -s` which reads the script from stdin
	startCmd := fmt.Sprintf("%s -s", shell)
	if err := session.Start(startCmd); err != nil {
		return "", "", -1, false, fmt.Errorf("failed to start ssh command: %w", err)
	}

	// write script body and close stdin to signal EOF
	if _, werr := stdinPipe.Write([]byte(fullScript)); werr != nil {
		return stdoutBuf.String(), stderrBuf.String(), -1, false, fmt.Errorf("failed to write script to ssh stdin: %w", werr)
	}
	if cerr := stdinPipe.Close(); cerr != nil {
		return stdoutBuf.String(), stderrBuf.String(), -1, false, fmt.Errorf("failed to close ssh stdin: %w", cerr)
	}

	// wait for command to complete, honoring timeout via context
	waitErr := make(chan error, 1)
	go func() {
		waitErr <- session.Wait()
	}()

	select {
	case werr := <-waitErr:
		// command finished on its own
		stdout = stdoutBuf.String()
		stderr = stderrBuf.String()
		if werr == nil {
			return stdout, stderr, 0, false, nil
		}
		// if the error is an ExitError, extract the exit code
		var exitErr *ssh.ExitError
		if errors.As(werr, &exitErr) {
			return stdout, stderr, exitErr.ExitStatus(), false, nil
		}
		// other connection error
		return stdout, stderr, -1, false, fmt.Errorf("ssh command failed: %w", werr)
	case <-ctx.Done():
		// timeout expired - kill the session
		_ = session.Signal(ssh.SIGKILL)
		_ = session.Close()
		// drain the wait channel to avoid leaking the goroutine
		<-waitErr
		return stdoutBuf.String(), stderrBuf.String(), -1, true, nil
	}
}

// buildScript assembles the full script to pipe to the remote shell, prefixing
// with `cd <workingDir>` when set and `export KEY=VALUE` statements for each
// entry in env.  The user's script is appended verbatim at the end.
func buildScript(script string, workingDir string, env []string) string {
	var b strings.Builder
	b.WriteString("set -e\n")
	if workingDir != "" {
		fmt.Fprintf(&b, "cd %s\n", shellQuote(workingDir))
	}
	for _, e := range env {
		if e == "" {
			continue
		}
		// env entries are KEY=VALUE - split on the first '=' to quote only the value
		parts := strings.SplitN(e, "=", 2)
		if len(parts) != 2 {
			// no '=' - export the bare name (unusual but harmless)
			fmt.Fprintf(&b, "export %s\n", parts[0])
			continue
		}
		fmt.Fprintf(&b, "export %s=%s\n", parts[0], shellQuote(parts[1]))
	}
	b.WriteString(script)
	if !strings.HasSuffix(script, "\n") {
		b.WriteString("\n")
	}
	return b.String()
}

// shellQuote wraps a string in single quotes, escaping any embedded single
// quotes so the value is safely interpolated into a shell command.
func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

// truncateMessage caps a message at maxEventMessageChars characters, appending
// a marker when truncation occurs so readers know the original was longer.
func truncateMessage(msg string) string {
	runes := []rune(msg)
	if len(runes) <= maxEventMessageChars {
		return msg
	}
	return string(runes[:maxEventMessageChars]) + "\n...[truncated]"
}

// sanitizeScriptOutput normalizes captured terminal output for storage in an
// event Note: strips ANSI escape sequences, and collapses carriage-return
// driven progress redraws so only the final state of each line remains.
func sanitizeScriptOutput(s string) string {
	if s == "" {
		return s
	}
	s = ansiEscape.ReplaceAllString(s, "")
	lines := strings.Split(s, "\n")
	for i, line := range lines {
		if idx := strings.LastIndex(line, "\r"); idx != -1 {
			lines[i] = line[idx+1:]
		}
	}
	return strings.Join(lines, "\n")
}
